admin_templates.template:
.userGroups li { float: left; width: 33%; }
{xen:helper clearfix, '.userGroups'}

.layoutGrid .SortColumn { min-height: 60px; margin: 0 0 10px; padding: 0; }
.layoutGrid .SortColumn .subHeading { margin: 10px; }
.layoutGrid .SortColumn .portlet { margin: 10px; border: 1px dotted {xen:property mutedTextColor}; text-align: center; cursor: move; }
.layoutGrid .SortColumn .portlet.custom { border: 1px solid {xen:property mutedTextColor}; font-weight: bold; }
.layoutGrid .SortColumn .portlet-placeholder { margin: 10px; border: 2px dashed {xen:property mutedTextColor}; height: 35px; }
.layoutGrid .SortColumn .portlet-placeholder * { visibility: hidden; }

.layoutGrid .SortColumn.disabled { min-height: 100px; }
.layoutGrid .SortColumn.disabled .portlet-placeholder,
.layoutGrid .SortColumn.disabled .portlet { width: 205px; float: left; margin: 0 0 10px 10px; }
{xen:helper clearfix, '.layoutGrid .SortColumn.disabled'}

.layoutGrid .SortColumn .controls { float: right; }
.layoutGrid .SortColumn .controls a { display: inline-block; width: 16px; height: 16px; }
.layoutGrid .SortColumn .controls .edit { background: transparent url('{xen:property imagePath}/xenforo/widgets/edit.png') no-repeat; }
.layoutGrid .SortColumn .controls .edit:hover { background-image: url('{xen:property imagePath}/xenforo/widgets/edit-hover.png'); }

.layoutGrid .sortLayout { margin: 10px; padding: 50px; border: 4px dashed {xen:property mutedTextColor}; text-align: center; font-size: 2em; }
{xen:helper clearfix, '.layoutGrid .activeColumns'}

.activeColumns { margin: -5px; }
.activeColumns table { width: 100%; }
.activeColumns table td { width: 25%; vertical-align: top; padding: 5px; }
.activeColumns table td .sectionMain { margin: 0; }
.activeColumns .leftColumn { min-height: 396px; }
.activeColumns .sideColumn { min-height: 540px; }

.notice { padding: 20px 0; background: #c44; color: #fff; text-align: center; }
.notice .head { font-size: 24px; font-weight: bold; }
.notice .foot { font-size: 12px; }




.hiddenOption   { display: inline-block; font-size: 9px; margin-right: 3px; color: {xen:property mutedTextColor}; }
.hiddenOption a { position: static; }
.optionList a.optionAnchor { position: absolute; top: -80px; } /* prevents anchors pointing going under the fixed header */

templates.template:
.xenForm .textHeading .selectAll { float: right; }
.xenForm .categoryUnit li { display: inline-block; width: 185px; }
.xenForm .categoryUnit dd { padding-right: 0px; }

.authorUnit .authorImage { float: left; }
.authorUnit .authorImage .img { display: block;width: 150px; height: 200px; }
.authorUnit .secondaryContent { margin-left: 160px; }
.authorUnit .secondaryContent .controls { float: right; margin-right: 10px; }
.authorUnit .secondaryContent .avatar { float: right; }
.authorUnit .secondaryContent .name { font-size: 28px; }
.authorUnit .secondaryContent .muted { margin-bottom: 15px; }
{xen:helper clearfix, '.authorUnit'}

.iconKey
{
	float: left; margin: 0 4px 0 0; height: 16px; width: 16px;
	background: transparent url('{xen:property imagePath}/xenforo/xenforo-ui-sprite.png') no-repeat 1000px 0;
}
.iconKey.category { background-position:   0px    1px; width: 14px; }
.iconKey.sticky   { background-position:   0px  -16px; }
.iconKey.redirect { background-position: -48px  -16px; }
.iconKey.redirect { background-position: -48px  -16px; }
.iconKey.comments { background-position: -65px  -16px; width: 14px; }
.iconKey.views	  { background-position: -144px -17px; width: 18px; }

.xenForm .date
{
	background-image: url("styles/8wayrun/calendar.png");
	background-position: right center;
	background-repeat: no-repeat;
}

.copyright { text-align: center; font-size: 11px; margin: 10px; clear: both; }

.articleControl { display: none; position: fixed; right: 10px; bottom: 0; z-index: 1000; }
.articleControl .resume { display: none; }
.articleControl .resume .muted { margin-bottom: 5px; font-size: 10px; text-align: center; }

.articleItem .singleLine { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

.articleItem .sectionMain { margin-bottom: 10px; }
.articleItem .subHeading { font-size: 18px; }
.articleItem .sectionFooter .iconKey { margin-top: 3px; }
.articleItem .sectionFooter .continue { float: right; }
.articleItem .sectionFooter .categories { margin-right: 90px; overflow: hidden; }
.articleItem .sectionFooter .categories li { display: inline-block; }
{xen:helper clearfix, '.articleItem .primaryContent'}
{xen:helper clearfix, '.articleItem .sectionFooter'}

.articleItem .dateBlock { float: left; margin: 10px 10px 0px -20px; text-align: center; position: relative; z-index: 100; }
.articleItem .dateBlock .heading { margin: 0; padding-bottom: 5px; text-transform: uppercase; }
.articleItem .dateBlock .secondaryContent { padding: 5px; font-weight: bold; font-size: 24px; }
.articleItem .excerptOffset { margin-left: 34px; }

.articleItem .messageUserBlock { float: right; margin-left: 10px; line-height: 0; }
.articleItem .medioHolder { display: block; background-size: 100%; }
.articleItem .medioHolder img { max-width: 200px; height: auto; }
.articleItem .attachHolder img { max-width: 200px; height: auto; }

.articleItem .metaData { margin-bottom: 10px; padding-bottom: 5px; border-bottom: 1px dashed {xen:property primaryLighterStill}; }
.articleItem .statData { float: right; margin-left: 10px; }

#infscr-loading
{
	position: fixed;
	right: 10px;
	bottom: 0;
	z-index: 1001;
	text-align: center;
	{xen:property sectionMain}
}

<xen:if is="{xen:property enableResponsive}">
@media (max-width:{xen:property maxResponsiveMediumWidth})
{
	.Responsive .articlesGrid .articleItem
	{
		width: 100%;
	}
}
</xen:if>

.tagList .tags { display: inline-block; }
.tagList .tags li { display: inline-block; margin: 3px; }

.tagList .tags li a[href] { position: relative; display: inline-block; text-decoration: none; }
.tagList .tags li .text
{
	background-color: #ccc; color: #333; font-size: 10px;
	height: 18px; line-height: 18px;
	margin-left: 6px; padding: 0 8px 0 12px;
}
.tagList .tags li .arrow
{
	position: absolute; top: 0; width: 0; height: 0;
	border-top: 9px solid transparent;
	border-bottom: 9px solid transparent; 
	border-right: 6px solid #ccc;
}
.tagList .tags li .circle
{
	position: absolute; top: 7px; left: 7px;
	width: 4px; height: 4px; border-radius: 50%;
	background-color: {xen:property primaryLightest};
}
.tagList .tags li:hover .arrow { border-right-color: #e00; }
.tagList .tags li:hover .text { background-color: #e00; color: #fff; }

.tagList .edit
{
	float: right; width: 16px; height: 16px;
	background: transparent url('{xen:property imagePath}/xenforo/widgets/edit.png') no-repeat;
}
.tagList .edit:hover { background-image: url('{xen:property imagePath}/xenforo/widgets/edit-hover.png'); }



.EWRporta2_ArticleView .messageArticle .messageUserInfo { display: none; }
.EWRporta2_ArticleView .messageArticle .messageInfo { margin-left: 0px; }

.EWRporta2_ArticleView .messageAuthor .avatar { float: left; }
.EWRporta2_ArticleView .messageAuthor .details { margin-left: 65px; padding-top: 38px; }
.EWRporta2_ArticleView .messageAuthor .addthis_toolbox,
.EWRporta2_ArticleView .messageAuthor .shareControl { float: right; }
{xen:helper clearfix, '.EWRporta2_ArticleView .messageAuthor'}

.EWRporta2_ArticleView .categories .iconKey { margin-top: 3px; }
.EWRporta2_ArticleView .categories li { display: inline-block; }



.EWRporta2_ArticleView .messageSimple .bbCodeBlock blockquote { display: block; }
.EWRporta2_ArticleView .messageSimple .editDate
{
	text-align: right;
	margin-top: 5px;
	font-size: 11px;
	color: {xen:property mutedTextColor};
}
.EWRporta2_ArticleView .messageSimple .newIndicator
{
	{xen:property messageNewIndicator}
}

.EWRporta2_ArticleView .tabs.onlyOne { display: none; }

.featuresGrid .featuresOuter
{
	position: relative;
	z-index: 1;
	border: 1px solid #333;
	background-color: #000;
	overflow: hidden; 
	-moz-border-radius: 5px;
	-webkit-border-radius: 5px;
	border-radius: 5px;
}

.featuresGrid ul li { background-repeat: no-repeat; background-position: center center; }
.featuresGrid ul li a { text-decoration: none !important; color: #EEE; }
.featuresGrid ul li .summary { position: absolute; bottom: 0px; width: 100%; background-color: rgba(0,0,0,0.5); }
.featuresGrid ul li .summary .title { padding: 15px 15px 0px; font-size: 18px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.featuresGrid ul li .summary .excerpt { padding: 0px 15px 15px; font-size: 11px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }


/*---------------------------------------*/
/*           BXSLIDER LAYOUT             */
/*---------------------------------------*/

/* ITEM CONTROLS */

.featuresGrid .bx-wrapper .bx-pager { position: absolute; top: 10px; width: 100%; text-align: center; }
.featuresGrid .bx-wrapper .bx-pager .bx-pager-item { position: relative; z-index: 999; display: inline-block; margin: 3px; }

.featuresGrid .bx-wrapper .bx-pager.bx-default-pager a
{
	width: 10px;
	height: 10px;
	display: block;
	text-indent: -9999px;
	-moz-border-radius: 5px;
	-webkit-border-radius: 5px;
	border-radius: 5px;
	box-shadow: 0px 0px 1px #FFF inset;
}
.featuresGrid .bx-wrapper .bx-pager.bx-default-pager a { background-color: rgba(128, 128, 128, 0.7); }
.featuresGrid .bx-wrapper .bx-pager.bx-default-pager a:hover { background-color: rgba(64, 64, 64, 0.7); }
.featuresGrid .bx-wrapper .bx-pager.bx-default-pager a.active { background-color: rgba(0, 0, 0, 1); }

/* DIRECTION CONTROLS */

.featuresGrid .bx-wrapper .bx-prev { left: 10px; background: url('styles/8wayrun/EWRporta2_slider.png') no-repeat 0 -32px; }
.featuresGrid .bx-wrapper .bx-prev:hover { background-position: 0 0; }

.featuresGrid .bx-wrapper .bx-next { right: 10px; background: url('styles/8wayrun/EWRporta2_slider.png') no-repeat -43px -32px; }
.featuresGrid .bx-wrapper .bx-next:hover { background-position: -43px 0; }

.featuresGrid .bx-wrapper .bx-controls-direction a
{
	position: absolute;
	top: 50%;
	width: 32px;
	height: 32px;
	margin-top: -16px;
	text-indent: -9999px;
	z-index: 100;
}
.featuresGrid .bx-wrapper .bx-controls-direction a.disabled { display: none; }

/* START/STOP CONTROLS */

.featuresGrid .bx-wrapper .bx-controls-auto { position: absolute; top: 10px; right: 10px; }
.featuresGrid .bx-wrapper .bx-controls-auto .bx-controls-auto-item { position: relative; z-index: 999; display: inline-block; margin: 3px; }
.featuresGrid .bx-wrapper .bx-controls-auto a
{
	display: block;
	text-indent: -9999px;
	width: 10px;
	height: 11px;
	background: url('styles/8wayrun/EWRporta2_slider.png') no-repeat;
}

.featuresGrid .bx-wrapper .bx-controls-auto .bx-start { background-position: -86px -11px; }
.featuresGrid .bx-wrapper .bx-controls-auto .bx-start:hover,
.featuresGrid .bx-wrapper .bx-controls-auto .bx-start.active { background-position: -86px 0; }

.featuresGrid .bx-wrapper .bx-controls-auto .bx-stop { background-position: -86px -44px; }
.featuresGrid .bx-wrapper .bx-controls-auto .bx-stop:hover,
.featuresGrid .bx-wrapper .bx-controls-auto .bx-stop.active { background-position: -86px -33px; }

.featuresGrid .bx-progress { height: 5px; border-top: 1px black solid; background-color: red; width: 0; position: absolute; bottom: 0; left: 0; z-index: 1000; }

.leftContainer { float: right; margin-left: -{xen:calc '{xen:property sidebar.width} + 10'}px; width: 100%; }
.leftContent { margin-left: {xen:calc '{xen:property sidebar.width} + 10'}px; }
.leftSidebar { float: left; }

.splitWidgets .section:first-child,
.splitWidgets .sectionMain:first-child { margin-top: 0; }

.sidebar.noFloats { float: none; width: auto; margin-bottom: 10px; }
.sidebar.b-rightWidgets { margin-left: {xen:calc '{xen:property sidebar.width} + 10'}px; }
.sidebar.b-leftWidgets { float: left; }
.sidebar.footerWidgets { clear: both; }
{xen:helper clearfix, '.splitWidgets'}

.copyright { text-align: center; font-size: 11px; margin: 10px; }

<xen:if is="{xen:property enableResponsive}">
	@media (max-width:{xen:property maxResponsiveWideWidth})
	{
		.Responsive .leftContainer { float: none; margin: 0 auto; }
		.Responsive .leftContent { margin-left: 0; }
	}
	@media (max-width:{xen:property maxResponsiveMediumWidth})
	{
		.Responsive .sidebar.b-leftWidgets { float: none; margin: 0 auto; }
		.Responsive .sidebar.b-rightWidgets { margin-left: 0px; }
	}
</xen:if>

.layoutGrid .SortColumn { min-height: 60px; margin: 0 0 10px; padding: 0; }
.layoutGrid .SortColumn .subHeading { margin: 10px; }
.layoutGrid .SortColumn .portlet { margin: 10px; border: 1px dotted {xen:property mutedTextColor}; text-align: center; cursor: move; }
.layoutGrid .SortColumn .portlet.locked { border: 3px solid {xen:property mutedTextColor}; font-weight: bold; cursor: no-drop; }
.layoutGrid .SortColumn .portlet-placeholder { margin: 10px; border: 2px dashed {xen:property mutedTextColor}; height: 35px; }
.layoutGrid .SortColumn .portlet-placeholder * { visibility: hidden; }

.layoutGrid .SortColumn.disabled { min-height: 100px; }
.layoutGrid .SortColumn.disabled .portlet-placeholder,
.layoutGrid .SortColumn.disabled .portlet { width: 165px; float: left; margin: 0 0 10px 10px; }
{xen:helper clearfix, '.layoutGrid .SortColumn.disabled'}

.layoutGrid .SortColumn .controls { float: right; }
.layoutGrid .SortColumn .controls a { display: inline-block; width: 16px; height: 16px; }
.layoutGrid .SortColumn .controls .edit { background: transparent url('{xen:property imagePath}/xenforo/widgets/edit.png') no-repeat; }
.layoutGrid .SortColumn .controls .edit:hover { background-image: url('{xen:property imagePath}/xenforo/widgets/edit-hover.png'); }

.layoutGrid .sortLayout { margin: 10px; padding: 50px; border: 4px dashed {xen:property mutedTextColor}; text-align: center; font-size: 2em; }
{xen:helper clearfix, '.layoutGrid .activeColumns'}

.activeColumns { margin: 0 -5px -10px; }
.activeColumns table { width: 100%; }
.activeColumns table td { width: 25%; vertical-align: top; padding: 5px; }
.activeColumns table td .sectionMain { margin: 0; }
.activeColumns .leftColumn { min-height: 397px; }
.activeColumns .sideColumn { min-height: 541px; }
